                       resume_hint={"thread": ev["thread_id"], "diff_stat": _diff_stat(cwd)})
            bus.log_run(task=log_task, role="execute", tier=log["executor"], account="codex", outcome="usage_limit",
                        cooldown_s=secs, **log)
